describe('Table Select All Rows with Header Checkbox', () => {
  beforeEach(() => {
    cy.visit('/table');
    cy.get('table').should('be.visible');
  });

  it('should select all rows when header checkbox is clicked', () => {
    // Get the header checkbox
    cy.get('thead input[type="checkbox"]').should('exist').click();

    // Verify all row checkboxes are checked
    cy.get('tbody input[type="checkbox"]').each(($checkbox) => {
      cy.wrap($checkbox).should('be.checked');
    });

    // Verify header checkbox is also checked
    cy.get('thead input[type="checkbox"]').should('be.checked');
  });

  it('should deselect all rows when header checkbox is clicked again', () => {
    // First, select all rows
    cy.get('thead input[type="checkbox"]').click();
    cy.get('tbody input[type="checkbox"]').should('be.checked');

    // Click header checkbox again to deselect all
    cy.get('thead input[type="checkbox"]').click();

    // Verify all row checkboxes are unchecked
    cy.get('tbody input[type="checkbox"]').each(($checkbox) => {
      cy.wrap($checkbox).should('not.be.checked');
    });

    // Verify header checkbox is also unchecked
    cy.get('thead input[type="checkbox"]').should('not.be.checked');
  });

  it('should handle table with no rows gracefully', () => {
    // Navigate to empty table
    cy.visit('/table-empty');

    // Header checkbox should still be visible and clickable
    cy.get('thead input[type="checkbox"]').should('exist').click();

    // Verify header checkbox is checked
    cy.get('thead input[type="checkbox"]').should('be.checked');

    // Verify no row checkboxes exist
    cy.get('tbody input[type="checkbox"]').should('not.exist');
  });

  it('should update header checkbox state when individual rows are manually selected', () => {
    // Manually select first row
    cy.get('tbody input[type="checkbox"]').first().click();

    // Header checkbox should remain unchecked (not all rows selected)
    cy.get('thead input[type="checkbox"]').should('not.be.checked');

    // Select all remaining rows
    cy.get('tbody input[type="checkbox"]').each(($checkbox) => {
      cy.wrap($checkbox).should('not.be.checked').click();
    });

    // Now header checkbox should be checked
    cy.get('thead input[type="checkbox"]').should('be.checked');
  });
});
